class UCI
{
 using Arguments = std::vector;
 using EngineOptions = std::map>;

 static constexpr int max\_depth = PLY\_MAX;

public:
 UCI(const std::string &name, const std::string &version)
 : \_name(name)
 , \_version(version)
 , \_use\_opening\_book(search::Context::\_book\_init(\_book))
 {
 set\_start\_position();

 search::Context::\_on\_iter = on\_iteration;

 \_options.emplace("algorithm", std::make\_shared(\_algorithm));
 \_options.emplace("best opening", std::make\_shared("Best Opening", \_best\_book\_move));
 \_options.emplace("debug", std::make\_shared("Debug", \_debug));
 \_options.emplace("ownbook", std::make\_shared("OwnBook", \_use\_opening\_book));
 \_options.emplace("ponder", std::make\_shared("Ponder", \_ponder));
 \_options.emplace("evalfile", std::make\_shared(\_eval\_file));
 \_options.emplace("syzygypath", std::make\_shared());
 }

 static bool output\_expected() { return \_output\_expected.load(std::memory\_order\_relaxed); }
 void run();

private:
 void dispatch(const std::string &, const Arguments &args);

 /\*\* UCI commands \*/
 void go(const Arguments &args);
 void isready();
 void ponderhit();
 void position(const Arguments &args);
 void setoption(const Arguments &args);
 void stop();
 void uci();
 void newgame();

 /\*\* Context callbacks \*/
 static void on\_iteration(PyObject \*, search::Context \*, const search::IterationInfo \*);

private:
 /\*\* position() helper \*/
 template  INLINE void apply\_moves(const T &moves)
 {
 \_last\_move = chess::BaseMove();
 \_ply\_count = 0;

 for (const auto &m : moves)
 if (m.size() >= 4)
 {
 chess::Square from, to;

 if (chess::parse\_square(m, from) && chess::parse\_square(std::string\_view(&m[2], 2), to))
 {
 const auto promo = m.size() > 4 ? chess::piece\_type(m[4]) : chess::PieceType::NONE;
 const auto move = chess::BaseMove(from, to, promo);
 const auto prev = \_buf.\_state;
 \_buf.\_state.apply\_move(move);
 chess::zobrist\_update(prev, move, \_buf.\_state);
 ASSERT(\_buf.\_state.\_hash == chess::zobrist\_hash(\_buf.\_state));
 /\* keep track of played moves, to detect repetitions \*/
 search::Context::\_history->emplace(\_buf.\_state);
 /\* update the halfmove clock \*/
 if (\_buf.\_state.capture\_value || prev.piece\_type\_at(from) == chess::PieceType::PAWN)
 search::Context::\_history->\_fifty = 0;
 else
 ++search::Context::\_history->\_fifty;
 \_last\_move = move;
 ++\_ply\_count;
 }
 }
 }

 INLINE search::Context &context() { return \*\_buf.as\_context(); }

 template 
 INLINE void output\_best\_move(bool request\_ponder = false)
 {
 if (output\_expected())
 {
 auto &ctxt = context();
 auto move = ctxt.\_best\_move;
 if (!move)
 if (auto first = ctxt.first\_valid\_move())
 move = \*first;
 if constexpr(synchronous)
 output\_best\_move(move, request\_ponder);
 else
 \_output\_pool->push\_task([this, move, request\_ponder] {
 output\_best\_move(move, request\_ponder);
 });
 }
 }

 INLINE void output\_best\_move(const chess::BaseMove &move, bool request\_ponder = false)
 {
 ASSERT(output\_expected());
 \_output\_expected = false;

 if (!move)
 {
 output("resign");
 }
 else
 {
 if (request\_ponder && \_ponder)
 {
 const auto &pv = \_tt.get\_pv();
 if (pv.size() > 2 && pv[1] == move)
 {
 output(std::format("bestmove {} ponder {}", move.uci(), pv[2].uci()));
 return;
 }
 }
 output(std::format("bestmove {}", move.uci()));
 }
 }

